// GQ has no coalesce or conditional expression, so "unknown" and "senior"/"active"
// cannot be produced as string values. This returns the raw city (null when missing)
// and a boolean flag for age >= 65 instead (null when age is missing).
query people_bands() {
    match {
        $p: Person
    }
    return {
        $p.name,
        $p.city,
        $p.age >= 65 as senior
    }
}
